fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    let n = s1.len();
    assert_eq!(n, s2.len(), "All input vectors must have the same length");
    assert_eq!(n, s3.len(), "All input vectors must have the same length");

    // Pre‐allocate exactly 3 * n elements
    let mut res = Vec::with_capacity(n * 3);

    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}

